@* Confirmation dialog for revoking a session *@

@if (Visible)
{
    <div class="modal-backdrop show" @onclick="Cancel"></div>
    <div class="modal d-block" tabindex="-1">
        <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="Cancel"></button>
                </div>
                <div class="modal-body">
                    <p>
                        Are you sure you want to revoke the session on
                        <strong>@SessionDevice</strong> from <strong>@SessionLocation</strong>?
                    </p>
                    <p class="text-muted">This will sign out that device immediately.</p>
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="Cancel">Cancel</button>
                    <button class="btn btn-danger" @onclick="Confirm">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public bool Visible { get; set; }
    [Parameter] public string SessionDevice { get; set; } = "";
    [Parameter] public string SessionLocation { get; set; } = "";
    [Parameter] public EventCallback OnConfirm { get; set; }
    [Parameter] public EventCallback OnCancel { get; set; }

    private async Task Confirm() => await OnConfirm.InvokeAsync();
    private async Task Cancel() => await OnCancel.InvokeAsync();
}

@using sv_8d06c9b96f0049719954656a90db6e3d.Models

<div class="settings-section">
    <h4>Profile</h4>
    <hr />

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success alert-dismissible fade show">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="displayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="bio"></textarea>
            </div>
        </div>
        <div class="col-md-4">
            <div class="avatar-preview text-center">
                <img src="@Profile.AvatarUrl"
                     alt="Avatar"
                     class="rounded-circle mb-2"
                     style="width:120px;height:120px;object-fit:cover;" />
                <div class="text-muted small text-break">@Profile.AvatarUrl</div>
            </div>
        </div>
    </div>

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
            @(isSaving ? "Saving…" : "Save Changes")
        </button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges">
            Discard Changes
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public UserProfile Profile { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string bio = "";
    private string? statusMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            ResetFields();
        }
    }

    private void ResetFields()
    {
        displayName = Profile.DisplayName;
        email = Profile.Email;
        bio = Profile.Bio;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        try
        {
            var updated = Profile with
            {
                DisplayName = displayName,
                Email = email,
                Bio = bio
            };
            await OnSave.InvokeAsync(updated);
            statusMessage = "Profile saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        ResetFields();
        statusMessage = null;
    }
}

