@using sv_8d06c9b96f0049719954656a90db6e3d.Models

<div class="settings-section">
    <h4>Appearance</h4>
    <hr />

    @if (!string.IsNullOrEmpty(statusMessage))
    {
        <div class="alert alert-success alert-dismissible fade show">
            @statusMessage
            <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
        </div>
    }

    <div class="row">
        <div class="col-md-7">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var t in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="theme-@t" value="@t"
                               checked="@(theme == t)"
                               @onchange="() => theme = t" />
                        <label class="form-check-label" for="theme-@t">@t</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check form-check-inline">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="fs-@size" value="@size"
                               checked="@(fontSize == size)"
                               @onchange="() => fontSize = size" />
                        <label class="form-check-label" for="fs-@size">@size</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" style="max-width:250px"
                        @bind="language">
                    @foreach (var lang in Languages)
                    {
                        <option value="@lang">@lang</option>
                    }
                </select>
            </div>

            <div class="mb-4">
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode"
                           checked="@compactMode"
                           @onchange="e => compactMode = (bool)e.Value!" />
                    <label class="form-check-label" for="compactMode">Compact Mode</label>
                </div>
            </div>

            <button class="btn btn-primary" @onclick="Save" disabled="@isSaving">
                @(isSaving ? "Saving…" : "Save")
            </button>
        </div>

        <div class="col-md-5">
            <h6>Live Preview</h6>
            <div class="appearance-preview @PreviewThemeClass"
                 style="font-size:@PreviewFontSize; padding:@PreviewPadding;">
                <div class="preview-header">
                    <strong>Dashboard</strong>
                </div>
                <div class="preview-body">
                    <p class="preview-text">
                        This is how your interface will look with the selected settings.
                    </p>
                    <div class="preview-card">
                        <span>Sample Card</span>
                        <small>@language · @theme theme</small>
                    </div>
                    <div class="preview-card">
                        <span>Another Item</span>
                        <small>Font: @fontSize</small>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public AppearanceSettings Settings { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private static readonly string[] Languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese"];

    private string theme = "Light";
    private string fontSize = "Medium";
    private string language = "English";
    private bool compactMode;
    private string? statusMessage;
    private bool isSaving;

    protected override void OnParametersSet()
    {
        if (!isSaving)
        {
            theme = Settings.Theme;
            fontSize = Settings.FontSize;
            language = Settings.Language;
            compactMode = Settings.CompactMode;
        }
    }

    private string PreviewThemeClass => theme switch
    {
        "Dark" => "preview-dark",
        "System" => "preview-system",
        _ => "preview-light"
    };

    private string PreviewFontSize => fontSize switch
    {
        "Small" => "0.85rem",
        "Large" => "1.15rem",
        _ => "1rem"
    };

    private string PreviewPadding => compactMode ? "0.5rem" : "1rem";

    private async Task Save()
    {
        isSaving = true;
        try
        {
            var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
            await OnSave.InvokeAsync(updated);
            statusMessage = "Appearance settings saved!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

