+    <SettingsSidebar ActiveSection="@activeSection"
+                     OnSectionChanged="section => activeSection = section" />
+
+    <div class="settings-content">
+        @if (isLoading)
+        {
+            <div class="d-flex justify-content-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading…</span>
+                </div>
+            </div>
+        }
+        else
+        {
+            @switch (activeSection)
+            {
+                case "Profile":
+                    <ProfileSection Profile="profile!" OnSave="SaveProfile" />
+                    break;
+                case "Notifications":
+                    <NotificationsSection Prefs="notificationPrefs!" OnSave="SaveNotifications" />
+                    break;
+                case "Security":
+                    <SecuritySection Security="securitySettings!"
+                                     OnChangePassword="HandleChangePassword"
+                                     OnRevokeSession="HandleRevokeSession" />
+                    break;
+                case "Appearance":
+                    <AppearanceSection Settings="appearance!" OnSave="SaveAppearance" />
+                    break;
+            }
+        }
+    </div>
+</div>
+
+@code {
+    private string activeSection = "Profile";
+    private bool isLoading = true;
+
+    private UserProfile? profile;
+    private NotificationPrefs? notificationPrefs;
+    private SecuritySettings? securitySettings;
+    private AppearanceSettings? appearance;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadAllSettings();
+        isLoading = false;
+    }
+
+    private async Task LoadAllSettings()
+    {
+        var tasks = new Task[]
+        {
+            Task.Run(async () => profile = await SettingsService.GetProfileAsync()),
+            Task.Run(async () => notificationPrefs = await SettingsService.GetNotificationPrefsAsync()),
+            Task.Run(async () => securitySettings = await SettingsService.GetSecuritySettingsAsync()),
+            Task.Run(async () => appearance = await SettingsService.GetAppearanceAsync())
+        };
+        await Task.WhenAll(tasks);
+    }
+
+    private async Task SaveProfile(UserProfile updated)
+    {
+        await SettingsService.SaveProfileAsync(updated);
+        profile = updated;
+    }
+
+    private async Task SaveNotifications(NotificationPrefs updated)
+    {
+        await SettingsService.SaveNotificationPrefsAsync(updated);
+        notificationPrefs = updated;
+    }
+
+    private async Task HandleChangePassword((string Current, string New) args)
+    {
+        await SettingsService.ChangePasswordAsync(args.Current, args.New);
+        securitySettings = await SettingsService.GetSecuritySettingsAsync();
+    }
+
+    private async Task HandleRevokeSession(string sessionId)
+    {
+        await SettingsService.RevokeSessionAsync(sessionId);
+        securitySettings = await SettingsService.GetSecuritySettingsAsync();
+    }
+
+    private async Task SaveAppearance(AppearanceSettings updated)
+    {
+        await SettingsService.SaveAppearanceAsync(updated);
+        appearance = updated;
+    }
+}
+

toolArgs.file_text:
/* ── Settings Dashboard Layout ── */

.settings-dashboard {
    display: flex;
    min-height: calc(100vh - 120px);
    gap: 0;
}

/* ── Sidebar ── */

.settings-sidebar {
    width: 220px;
    min-width: 220px;
    background: #f8f9fa;
    border-right: 1px solid #dee2e6;
    padding: 1.5rem 0;
}

.sidebar-title {
    padding: 0 1.25rem 0.75rem;
    margin: 0;
    color: #6c757d;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.settings-sidebar .nav-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    text-align: left;
    font-size: 0.95rem;
    border-left: 3px solid transparent;
    transition: all 0.15s ease;
    cursor: pointer;
}

.settings-sidebar .nav-link:hover {
    background: #e9ecef;
    color: #212529;
}

.settings-sidebar .nav-link.active {
    background: #e7f1ff;
    color: #0d6efd;
    border-left-color: #0d6efd;
    font-weight: 600;
}

.section-icon {
    font-size: 1.1rem;
}

/* ── Content area ── */

.settings-content {
    flex: 1;
    padding: 1.5rem 2rem;
    max-width: 900px;
}

.settings-section h4 {
    margin-bottom: 0.25rem;
}

/* ── Appearance preview ── */

.appearance-preview {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    overflow: hidden;
    transition: all 0.2s ease;
}

.appearance-preview.preview-light {
    background: #ffffff;
    color: #212529;
}

.appearance-preview.preview-dark {
    background: #1e1e2e;
    color: #cdd6f4;
    border-color: #45475a;
}

.appearance-preview.preview-system {
    background: linear-gradient(135deg, #ffffff 50%, #1e1e2e 50%);
    color: #495057;
}

.preview-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid rgba(128, 128, 128, 0.2);
}

.preview-body {
    padding: 0.75rem 1rem;
}

.preview-text {
    font-size: inherit;
    margin-bottom: 0.75rem;
    opacity: 0.85;
}

.preview-card {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.5rem 0.75rem;
    border: 1px solid rgba(128, 128, 128, 0.2);
    border-radius: 0.375rem;
    margin-bottom: 0.5rem;
    font-size: inherit;
}

.preview-card small {
    opacity: 0.6;
}

/* ── Modal backdrop ── */

::deep .modal-backdrop.show {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.5);
    z-index: 1040;
}

::deep .modal.d-block {
    position: fixed;
    inset: 0;
    z-index: 1050;
    display: flex !important;
    align-items: center;
    justify-content: center;
}

/* ── Avatar ── */

.avatar-preview {
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 0.5rem;
    border: 1px solid #dee2e6;
}

